function updateHotspots(){if(!main)return;const canvas=main.canvas.getBoundingClientRect(),overlays=$$(".room-heading,.room-navigation,.guide-bar,.view-tools,.header,.side-tools").filter(el=>el.getClientRects().length).map(el=>el.getBoundingClientRect());$$(".hotspot").forEach((el,i)=>{const p=points()[i],position=main.project(room().yaw+p.offset,p.pitch);let blocked=false;if(position){const x=canvas.left+position.x*canvas.width,y=canvas.top+position.y*canvas.height,half=p.kind==="nav"?50:23;blocked=overlays.some(b=>x+half>b.left&&x-half<b.right&&y+24>b.top&&y-24<b.bottom);el.style.left=`${position.x*100}%`;el.style.top=`${position.y*100}%`;}el.hidden=!position||!main.ready||compareOpen||blocked;});$$(".plan-map").forEach(el=>el.style.setProperty("--view-angle",`${main.yaw-room().yaw}deg`));}
function renderHotspots(){$("#hotspots").innerHTML=points().map((p,i)=>`<button class="hotspot ${p.kind==="nav"?"nav-hotspot":""}" data-point="${i}" aria-label="${p.kind==="nav"?"Go to ":""}${p.title}">${icon({info:"info",nav:"right",video:"play",link:"external"}[p.kind])}${p.kind==="nav"?`<span>${p.title}</span>`:""}</button>`).join("");updateHotspots();}
function closeHotspot(){$("#hotspot-card").hidden=true;}
function openPoint(index){const p=points()[index];if(p.kind==="nav"){changeRoom((current+1)%rooms.length);return;}if(p.kind==="video"){openVideo("walkthrough");return;}$("#hotspot-kind").textContent=p.kind==="link"?"EXTERNAL RESOURCE":"ILLUSTRATIVE FEATURE";$("#hotspot-title").textContent=p.title;$("#hotspot-body").textContent=p.body;$("#hotspot-link").hidden=!p.url;if(p.url)$("#hotspot-link").href=p.url;$("#hotspot-card").hidden=false;}
function planMarkup(){return rooms.map((r,i)=>`<button class="plan-room" data-room="${i}" aria-current="${i===current}" aria-label="View ${r.name} on the illustrative plan">${icon("pin")}<span>${r.short}</span></button>`).join("");}
function updatePlans(){$$(".plan-map").forEach(el=>el.innerHTML=planMarkup());}
function updateRoomUI(){
 const r=room();$("#current-room").textContent=r.name;$("#room-dimensions").textContent=`${r.width} × ${r.depth} ft`;$("#room-subtitle").textContent=r.subtitle;$$(".room-thumb").forEach((el,i)=>el.setAttribute("aria-current",String(i===current)));updatePlans();renderHotspots();
}
async function changeRoom(index,{guided=false}={}){if(!guided)pauseGuide();current=(index+rooms.length)%rooms.length;gyroBase=null;guideElapsed=0;closeHotspot();updateRoomUI();history.replaceState(null,"",`#room=${room().id}`);await main.load(room());if(guideRunning)narrate();}
$("#room-strip").innerHTML=rooms.map((r,i)=>`<button class="room-thumb" data-room="${i}" aria-label="Explore ${r.name}" aria-current="${i===0}"><img src="${thumbnail(r)}" width="320" height="200" alt="${r.description}"><span>${r.short}</span></button>`).join("");
$("#text-rooms").innerHTML=rooms.map(r=>`<article><h4>${r.name}</h4><p>${r.description}</p><p>Illustrative plan: ${r.width} × ${r.depth} ft. ${r.note}</p></article>`).join("");
$("#comparison-room").innerHTML=rooms.map((r,i)=>`<option value="${i}">${r.name}</option>`).join("");
main=new Panorama($("#panorama"),updateHotspots);
function setRotate(value){rotateOn=!!value&&!reduced&&!gyroOn;$("#auto-rotate").setAttribute("aria-pressed",String(rotateOn));if(value&&!rotateOn)toast("Auto-rotation stays off while reduced motion or motion controls are enabled.");}
function setMini(value){miniVisible=value;$("#minimap").hidden=!value;const input=$("#mini-toggle");if(input)input.checked=value;}
function updateGuide(){$("#play").setAttribute("aria-pressed",String(guideRunning));$("#play").setAttribute("aria-label",guideRunning?"Pause guided tour":"Play guided tour");$("#play").innerHTML=icon(guideRunning?"pause":"play");$("#mode .mode-long").textContent=guideRunning?"Guided tour":"Self-guided";$("#mode .mode-short").textContent=guideRunning?"Guided":"Self";$("#mode").setAttribute("aria-label",guideRunning?"Switch to self-guided tour":"Switch to guided tour");}
function pauseGuide(){guideRunning=false;updateGuide();if("speechSynthesis"in window)speechSynthesis.cancel();}
function localVoice(){return "speechSynthesis"in window?speechSynthesis.getVoices().find(v=>v.localService&&v.lang.startsWith("en")):null;}
function narrate(){if(!narrationOn||!guideRunning)return;const voice=localVoice();if(!voice){toast("No local English voice is available. The complete transcript is available instead.");return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(room().narration);utterance.voice=voice;utterance.rate=.92;speechSynthesis.speak(utterance);}
function playGuide(){guideRunning=true;setRotate(false);guideElapsed=0;updateGuide();narrate();toast("Guided tour playing. Each room lasts 12 seconds; use previous or next to skip.");}
let lastFrame=performance.now();function animate(now){const dt=Math.min((now-lastFrame)/1000,.1);lastFrame=now;if(!document.hidden&&!$("#drawer").open&&!$("#schedule-dialog").open&&!$("#media-dialog").open&&!xrSession){if(rotateOn)main.set(main.yaw+dt*3);if(guideRunning&&main.ready){guideElapsed+=dt;$("#guide-progress").style.width=`${Math.min(guideElapsed/12,1)*90}%`;if(guideElapsed>=12)changeRoom((current+1)%rooms.length,{guided:true});}}requestAnimationFrame(animate);}requestAnimationFrame(animate);
function openCompare(){compareOpen=!compareOpen;pauseGuide();setRotate(false);closeHotspot();$("#comparison-view").hidden=!compareOpen;$("#scene").classList.toggle("comparing",compareOpen);$("#compare").setAttribute("aria-pressed",String(compareOpen));if(compareOpen){if(!reference)reference=new Panorama($("#comparison-panorama"));const n=current===0?3:0;$("#comparison-room").value=String(n);reference.load(rooms[n]);toast("Compare independent stock spaces side by side. Each view has its own camera.");}updateHotspots();}
$("#compare").addEventListener("click",openCompare);$("#close-compare").addEventListener("click",()=>{if(compareOpen)openCompare();});$("#comparison-room").addEventListener("change",e=>reference.load(rooms[Number(e.target.value)]));
$("#zoom-in").addEventListener("click",()=>{main.interact();main.set(main.yaw,main.pitch,main.fov-5);});$("#zoom-out").addEventListener("click",()=>{main.interact();main.set(main.yaw,main.pitch,main.fov+5);});$("#reset").addEventListener("click",()=>{main.interact();main.set(room().yaw,0,main.homeFov);});
$("#auto-rotate").addEventListener("click",()=>{pauseGuide();setRotate(!rotateOn);});$("#play").addEventListener("click",()=>guideRunning?pauseGuide():playGuide());$("#mode").addEventListener("click",()=>guideRunning?pauseGuide():playGuide());$("#previous-room").addEventListener("click",()=>changeRoom(current-1,{guided:guideRunning}));$("#next-room").addEventListener("click",()=>changeRoom(current+1,{guided:guideRunning}));
$("#narration").addEventListener("click",()=>{narrationOn=!narrationOn;$("#narration").setAttribute("aria-pressed",String(narrationOn));$("#narration").setAttribute("aria-label",narrationOn?"Turn off local narration":"Turn on local narration");$("#narration").innerHTML=icon(narrationOn?"sound":"mute");if(!narrationOn&&"speechSynthesis"in window)speechSynthesis.cancel();else if(narrationOn){if(!localVoice())toast("Narration requested. No local English voice is available; read the transcript.");else narrate();}});
$("#fullscreen").addEventListener("click",async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($("#tour").requestFullscreen)await $("#tour").requestFullscreen();else toast("Fullscreen is unavailable in this browser. Rotate your device for a wider view.");}catch{toast("Fullscreen could not start in this browser.");}});
document.addEventListener("fullscreenchange",()=>{$("#fullscreen").setAttribute("aria-label",document.fullscreenElement?"Exit fullscreen":"Enter fullscreen");$("#fullscreen").innerHTML=icon(document.fullscreenElement?"collapse":"expand");});
$("#save").addEventListener("click",e=>{const saved=e.currentTarget.getAttribute("aria-pressed")!=="true";e.currentTarget.setAttribute("aria-pressed",String(saved));toast(saved?"Saved for this tab only. No account or persistent storage is used.":"Removed from this tab’s saved homes.");});
$("#hide-minimap").addEventListener("click",()=>setMini(false));
function openDrawer(name){
 panel=name;closeHotspot();const titles={room:room().name,floorplan:"Find your way.",gallery:"A closer look.",settings:"Make yourself at home.",transcript:"The tour, in words.",details:"The finer details.",measure:"Will your couch fit?",lighting:"A change of light.",share:"A place worth sharing."};
 $("#drawer-title").textContent=titles[name]||"Explore";$("#drawer-eyebrow").textContent={room:"ROOM NOTES",floorplan:"ILLUSTRATIVE MAIN LEVEL",gallery:"PHOTOGRAPHY & FILM",settings:"TOUR TOOLS",measure:"SCHEMATIC MEASUREMENT",share:"SHARE THIS TOUR"}[name]||"THE ALDER HOUSE";
 const content=$("#drawer-content"),r=room();
 if(name==="room")content.innerHTML=`<img class="panel-photo" src="${photo(r)}" width="640" height="400" alt="${r.description}"><div class="dimensions">${icon("ruler")} ${r.width} × ${r.depth} ft · illustrative plan</div><p>${r.description}</p><h3>Considered details</h3><ul>${r.features.map(f=>`<li>${f}</li>`).join("")}</ul><p class="note">${r.note}</p><h3>Room photographs</h3><div class="panel-gallery">${[0,1,2,3].map(n=>`<button class="photo-button" data-photo="${n}"><img src="${photo(r,n)}" width="640" height="400" alt="Perspective ${n+1} of the ${r.name.toLowerCase()} panorama"><span>Perspective ${n+1} ${icon("arrow")}</span></button>`).join("")}</div><h3>Points of interest</h3><div class="point-list">${points().map((p,i)=>`<button data-panel-point="${i}">${p.title}${icon(p.kind==="nav"?"right":"plus")}</button>`).join("")}</div><button class="text-button" data-panel="measure">Try furniture on the plan ${icon("arrow")}</button>`;
 if(name==="floorplan")content.innerHTML=`<p>Explore four spaces from this conceptual main-level plan. The outline, dimensions and connections are illustrative, not a measured survey of the independent panorama locations.</p><div class="large-plan"><div class="plan-map" data-plan="large"></div></div><div class="legend"><span><i></i> Current room</span><span><i></i> Living spaces</span></div><label class="toggle-row"><span><strong>Corner mini map</strong><small>Keep the plan in view while exploring.</small></span><input id="mini-toggle" type="checkbox" ${miniVisible?"checked":""}></label><button class="text-button" data-panel="measure">Measure the schematic plan ${icon("ruler")}</button>`;
 if(name==="gallery")content.innerHTML=`<p>Real 360° photography, perspective studies and short films. These independent stock locations are not a connected property scan.</p><h3>Room photographs</h3><div class="gallery-grid">${rooms.map((v,i)=>`<button class="media-tile" data-gallery-room="${i}"><img src="${photo(v)}" width="640" height="400" alt="${v.description}"><span>${v.name}${icon("expand")}</span><small>Photograph · panorama projection</small></button>`).join("")}</div><h3>In motion</h3><div class="gallery-grid"><button class="media-tile" data-video="walkthrough"><img src="${photo(rooms[0])}" width="640" height="400" alt="Garden-facing lounge"><span>Virtual look-around${icon("play")}</span><small>Original viewer recording · not an in-person walkthrough</small></button><button class="media-tile" data-video="aerial"><img src="assets/aerial-poster.jpg" width="640" height="360" alt="Stock drone view of a residential neighborhood"><span>Above the neighborhood${icon("play")}</span><small>Genuine unrelated stock drone footage</small></button><button class="media-tile" data-video="neighborhood"><img src="assets/aerial-poster.jpg" width="640" height="360" alt="Neighborhood streets and homes viewed from above"><span>A neighborhood moment${icon("play")}</span><small>Another excerpt of the same stock clip; not verified Austin</small></button></div><button class="text-button" data-panel="lighting">Explore the lighting comparison ${icon("sun")}</button><p class="note">Panoramas: Greg Zaal / Poly Haven, CC0. Drone footage: CAPTKHO kho / Pexels. <a href="assets/CREDITS.txt">Read asset credits.</a></p>`;
 if(name==="details")content.innerHTML=`<img class="panel-photo" src="${photo(rooms[0])}" width="640" height="400" alt="${rooms[0].description}"><h3>1840 Alder Lane · Austin, TX</h3><p>Fictional listing · $1,250,000 · 4 bed · 3.5 bath · 3,200 sq ft.</p><ul><li>Four independently sourced 360° room studies</li><li>Garden-facing living-room concept</li><li>Open kitchen and flexible studio concept</li><li>Illustrative hardwood, built-in shelving and 2023 HVAC specifications</li></ul><dl class="data-list">${[["School district","Not supplied or verified"],["Property tax","Not supplied or verified"],["HOA dues & rules","Not supplied or verified"],["Parcel & survey","Not supplied"],["Agent & brokerage","No live agent supplied"]].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join("")}</dl><p class="note">Price, address, dimensions, features and specifications belong to a fictional concept. Obtain real listing documents and independent professional advice before relying on property information.</p><button class="button" data-more-info>Preview an information request ${icon("arrow")}</button>`;
 if(name==="transcript")content.innerHTML=`<p>Read the entire tour without sound or interactive graphics. Guided playback spends 12 seconds per room. Narration uses a local English system voice only when explicitly enabled and available.</p>${rooms.map((v,i)=>`<article class="transcript-item"><h3>${v.name}</h3><p>${v.narration}</p><button data-room="${i}">Explore ${v.name} ${icon("arrow")}</button></article>`).join("")}`;
 if(name==="settings")content.innerHTML=`<p>A quieter way to explore. Your preferences apply to this tab only.</p><label class="toggle-row"><span><strong>High contrast</strong><small>Stronger panels, borders and focus indicators.</small></span><input id="contrast-toggle" type="checkbox" ${highContrast?"checked":""}></label><label class="toggle-row"><span><strong>Reduced motion</strong><small>Respects your system setting; disables auto-rotation.</small></span><input id="motion-toggle" type="checkbox" ${reduced?"checked":""}></label><label class="toggle-row"><span><strong>Corner mini map</strong><small>Click a space to change rooms.</small></span><input id="mini-toggle" type="checkbox" ${miniVisible?"checked":""}></label><label class="toggle-row"><span><strong>Motion controls</strong><small>Permission-based device orientation.</small></span><input id="gyro-toggle" type="checkbox" ${gyroOn?"checked":""}></label><label class="toggle-row"><span><strong>Ambient sound</strong><small>Original soft synthesized tones. Off by default.</small></span><input id="music-toggle" type="checkbox" ${musicOn?"checked":""}></label><label style="margin-top:22px">Panorama quality<select id="quality-select"><option value="auto" ${quality==="auto"?"selected":""}>Auto · connection-aware</option><option value="1k" ${quality==="1k"?"selected":""}>1K · save bandwidth</option><option value="2k" ${quality==="2k"?"selected":""}>2K · more detail</option></select></label><p class="tool-note" id="device-note" role="status">${xrSupported?"Compatible WebXR runtime detected. A headset is still required.":"VR requires a supported WebXR headset/browser and a secure origin."}</p><div class="tool-grid"><button id="vr-start">${icon("vr")} ${xrSession?"End VR session":"Explore in VR"}</button><button data-compare>${icon("compare")} Compare spaces</button><button data-panel="measure">${icon("ruler")} Measure & furnish</button><button data-panel="lighting">${icon("sun")} Lighting study</button><button data-panel="details">${icon("house")} Property details</button><button data-share>${icon("share")} Share tour</button></div><p class="note">Keyboard: focus the panorama, use arrow keys to turn, + / − to zoom and Home to reset. All room choices and points of interest also have text controls. Device motion and headset behavior depend on actual hardware.</p>`;
 if(name==="measure"){renderMeasurement(content);}
 if(name==="lighting")content.innerHTML=`<p>One photograph, two moods. Drag the slider to compare the original with a warm color treatment. This is a lighting study, not a renovation or staged/empty comparison.</p><div class="lighting-frame"><img src="${photo(r)}" width="640" height="400" alt="Original perspective of ${r.name}"><div class="lighting-warm" id="lighting-warm"><img src="${photo(r)}" width="640" height="400" alt="The same photograph with a warm color treatment"></div></div><div class="lighting-labels"><span>Warm treatment</span><span>Original photograph</span></div><label>Comparison position<input id="lighting-slider" type="range" min="0" max="100" value="50"></label><p class="note">A purely illustrative CSS color adjustment. No materials, furniture or room geometry have changed.</p>`;
 if(name==="share"){renderShare(content);}
 updatePlans();if(name==="settings"){const select=$("#quality-select");select.add(new Option("4K · full detail","4k"));select.value=quality;}if(!$("#drawer").open)$("#drawer").showModal();
}
function closeDrawer(){$("#drawer").close();}
$("#drawer").addEventListener("close",()=>{panel="";$("#drawer-content").replaceChildren();});
function renderShare(content){
 content.innerHTML=`<p>Share the current room, or copy a responsive iframe embed. On a local preview, the link and QR code work only where that preview is reachable; publish the static page before sharing publicly.</p><label>Tour link<textarea class="share-field" id="share-url" readonly rows="3"></textarea></label><div class="share-actions"><button class="button" data-copy="share-url">${icon("copy")}Copy link</button><a id="email-tour">${icon("mail")}Email to a friend</a></div><label>Responsive embed code<textarea class="share-field" id="embed-code" readonly rows="5"></textarea></label><button class="button" data-copy="embed-code">${icon("copy")}Copy embed</button><div class="qr-frame" id="qr-frame" aria-label="QR code for the current tour link"></div><p class="note">The QR code is generated locally. Forms, contact details and preferences are never included in the shared URL.</p><p id="copy-status" role="status"></p>`;
 const url=new URL(location.href);url.hash=`room=${room().id}`;url.search="";$("#share-url").value=url.href;$("#embed-code").value=`<iframe src="${url.href.replaceAll("&","&amp;").replaceAll('"',"&quot;")}" title="The Alder House virtual tour" style="width:100%;height:90vh;border:0" allow="fullscreen; xr-spatial-tracking" loading="lazy"></iframe>`;$("#email-tour").href=`mailto:?subject=${encodeURIComponent("A closer look at The Alder House")}&body=${encodeURIComponent(`Explore this fictional 360-degree property concept: ${url.href}`)}`;const qr=qrcode(0,"M");qr.addData(url.href);qr.make();$("#qr-frame").innerHTML=qr.createSvgTag({cellSize:4,margin:4,scalable:true});$("#qr-frame svg").setAttribute("role","img");$("#qr-frame svg").setAttribute("aria-label","Scannable QR code containing the tour link above");
}
async function copyField(id){const field=document.getElementById(id);try{await navigator.clipboard.writeText(field.value);$("#copy-status").textContent="Copied. Local preview links are not public URLs.";}catch{field.focus();field.select();$("#copy-status").textContent="Clipboard unavailable. The text is selected; copy it with your keyboard.";} }
let measurePoints=[],measureCursor=null,sofaState={width:84,depth:36,rotated:false,x:.5,y:.55},sofaDrag=null;
function renderMeasurement(content){measurePoints=[];sofaState={width:84,depth:36,rotated:false,x:.5,y:.55};const r=room();content.innerHTML=`<p>Measure two points on this ${r.width} × ${r.depth} ft <strong>illustrative room plan</strong>. The panorama has no depth calibration; these are not on-site measurements.</p><label>Room<select id="measure-room">${rooms.map((v,i)=>`<option value="${i}" ${i===current?"selected":""}>${v.name} · ${v.width} × ${v.depth} ft</option>`).join("")}</select></label><div class="measure-surface" id="measure-surface" style="--plan-ratio:${r.width/r.depth}" tabindex="0" role="group" aria-label="Illustrative room plan. Click two points to measure. The sofa can be dragged or moved with arrow keys."><svg id="measurement-lines" viewBox="0 0 ${r.width} ${r.depth}" preserveAspectRatio="none" aria-hidden="true"></svg><button class="sofa" id="sofa" aria-label="Move the illustrative sofa with arrow keys or drag">${icon("sofa")}</button></div><output class="measure-result" id="measure-result" aria-live="polite">Choose a first point</output><div class="measurement-actions"><button id="clear-measure">Clear points</button><button id="rotate-sofa">${icon("rotate")} Rotate sofa</button></div><h3>Will my couch fit?</h3><div class="form-pair"><label>Sofa length (inches)<input type="number" id="sofa-width" min="12" max="360" step="1" value="84"></label><label>Sofa depth (inches)<input type="number" id="sofa-depth" min="12" max="360" step="1" value="36"></label></div><output class="fit-result" id="fit-result" aria-live="polite"></output><p class="note">Fit checks only the rectangular footprint and rotation in this sample plan. Doorways, stairs, circulation, ceiling height and real room dimensions still need independent measurement.</p>`;updateSofa();bindMeasurement();}
function updateSofa(){const r=room(),a=$("#sofa-width"),b=$("#sofa-depth"),out=$("#fit-result");if(!a||!b)return;const valid=a.checkValidity()&&b.checkValidity()&&a.value!==""&&b.value!=="";$("#sofa").hidden=!valid;if(!valid){out.textContent="Enter whole-inch dimensions from 12 to 360.";out.className="fit-result no-fit";return;}sofaState.width=Number(a.value);sofaState.depth=Number(b.value);const w=(sofaState.rotated?sofaState.depth:sofaState.width)/12,d=(sofaState.rotated?sofaState.width:sofaState.depth)/12,fit=w<=r.width&&d<=r.depth,sofa=$("#sofa");Object.assign(sofa.style,{width:`${w/r.width*100}%`,height:`${d/r.depth*100}%`,left:`${Math.max(0,r.width-w)*sofaState.x/r.width*100}%`,top:`${Math.max(0,r.depth-d)*sofaState.y/r.depth*100}%`});sofa.classList.toggle("too-large",!fit);out.className=`fit-result${fit?"":" no-fit"}`;out.textContent=fit?`Fits within the modeled footprint: ${w.toFixed(2)} × ${d.toFixed(2)} ft. Remaining span: ${(r.width-w).toFixed(2)} × ${(r.depth-d).toFixed(2)} ft.`:`Does not fit within this ${r.width} × ${r.depth} ft sample room at this rotation.`;}
function drawMeasurement(){const svg=$("#measurement-lines"),r=room();svg.replaceChildren();if(measurePoints.length===2){const line=document.createElementNS("http://www.w3.org/2000/svg","line");for(const[key,val]of Object.entries({x1:measurePoints[0].x,y1:measurePoints[0].y,x2:measurePoints[1].x,y2:measurePoints[1].y}))line.setAttribute(key,val);svg.append(line);}measurePoints.forEach(p=>{const circle=document.createElementNS("http://www.w3.org/2000/svg","circle");circle.setAttribute("cx",p.x);circle.setAttribute("cy",p.y);circle.setAttribute("r",r.width*.009);svg.append(circle);});$("#measure-result").textContent=measurePoints.length===2?`${Math.hypot(measurePoints[1].x-measurePoints[0].x,measurePoints[1].y-measurePoints[0].y).toFixed(2)} ft · illustrative plan`:measurePoints.length?"Choose a second point":"Choose a first point";}
function bindMeasurement(){
 const surface=$("#measure-surface"),sofa=$("#sofa");
 sofa.insertAdjacentHTML("beforeend",'<span aria-hidden="true">SOFA</span>');
 measureCursor=null;surface.setAttribute("aria-label","Illustrative room plan. Click two points, or use Home for the origin, End for the opposite corner, arrow keys to move a one-foot cursor, and Enter to place a point. The sofa has separate arrow-key controls.");
 surface.addEventListener("keydown",e=>{if(e.target!==surface||!["Home","End","ArrowLeft","ArrowRight","ArrowUp","ArrowDown","Enter"," "].includes(e.key))return;e.preventDefault();const r=room();measureCursor??={x:0,y:0};if(e.key==="Home")measureCursor={x:0,y:0};else if(e.key==="End")measureCursor={x:r.width,y:r.depth};else if(e.key==="Enter"||e.key===" "){if(measurePoints.length===2)measurePoints=[];measurePoints.push({...measureCursor});}else{measureCursor.x=clamp(measureCursor.x+(e.key==="ArrowLeft"?-1:e.key==="ArrowRight"?1:0),0,r.width);measureCursor.y=clamp(measureCursor.y+(e.key==="ArrowUp"?-1:e.key==="ArrowDown"?1:0),0,r.depth);}drawMeasurement();const cursor=document.createElementNS("http://www.w3.org/2000/svg","path");cursor.setAttribute("d",`M${measureCursor.x-.4} ${measureCursor.y}h.8M${measureCursor.x} ${measureCursor.y-.4}v.8`);$("#measurement-lines").append(cursor);surface.setAttribute("aria-description",`Measurement cursor: ${measureCursor.x} by ${measureCursor.y} feet. Press Enter to place this point.`);});
 surface.addEventListener("click",e=>{if(e.target.closest("#sofa"))return;const box=surface.getBoundingClientRect(),r=room();if(measurePoints.length===2)measurePoints=[];measurePoints.push({x:clamp((e.clientX-box.left-2)/(box.width-4),0,1)*r.width,y:clamp((e.clientY-box.top-2)/(box.height-4),0,1)*r.depth});drawMeasurement();});
 sofa.addEventListener("pointerdown",e=>{e.stopPropagation();sofa.setPointerCapture(e.pointerId);sofaDrag={x:e.clientX,y:e.clientY,sx:sofaState.x,sy:sofaState.y};});
 sofa.addEventListener("pointermove",e=>{if(!sofaDrag)return;const box=surface.getBoundingClientRect(),r=room(),w=(sofaState.rotated?sofaState.depth:sofaState.width)/12,d=(sofaState.rotated?sofaState.width:sofaState.depth)/12;sofaState.x=clamp(sofaDrag.sx+(e.clientX-sofaDrag.x)/Math.max(1,box.width*(1-w/r.width)),0,1);sofaState.y=clamp(sofaDrag.sy+(e.clientY-sofaDrag.y)/Math.max(1,box.height*(1-d/r.depth)),0,1);updateSofa();});const end=()=>sofaDrag=null;sofa.addEventListener("pointerup",end);sofa.addEventListener("pointercancel",end);
 sofa.addEventListener("keydown",e=>{if(!["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(e.key))return;e.preventDefault();sofaState.x=clamp(sofaState.x+(e.key==="ArrowLeft"?-.05:e.key==="ArrowRight"?.05:0),0,1);sofaState.y=clamp(sofaState.y+(e.key==="ArrowUp"?-.05:e.key==="ArrowDown"?.05:0),0,1);updateSofa();});
}
function showMedia(title,caption){$("#media-title").textContent=title;$("#media-caption").textContent=caption;if(!$("#media-dialog").open)$("#media-dialog").showModal();}
function openPhoto(r,n=r.photo){$("#media-content").innerHTML=`<img src="${photo(r,n)}" width="640" height="400" alt="${r.description}">`;showMedia(r.name,"A genuine perspective projection of independent CC0 360° photography by Greg Zaal / Poly Haven. Not a verified view of the fictional address.");}
function openVideo(kind){const walkthrough=kind==="walkthrough",webm=kind!=="aerial";$("#media-content").innerHTML=`<video id="tour-video" controls playsinline preload="metadata" ${walkthrough?`poster="${photo(rooms[0])}"`:'poster="assets/aerial-poster.jpg"'}><source src="assets/${walkthrough?"walkthrough.webm":kind==="neighborhood"?"neighborhood.webm":"aerial.mp4"}" type="${webm?"video/webm":"video/mp4"}">Your browser cannot play this video.</video>`;showMedia(walkthrough?"A virtual look-around":kind==="aerial"?"Above the neighborhood":"A neighborhood moment",walkthrough?"Original recording of this stock-panorama viewer. An illustrative virtual look-around, not an actual continuous property walkthrough.":"Genuine stock drone footage by CAPTKHO kho / Pexels. An unrelated residential area, not this house or a verified Austin neighborhood. The neighborhood entry is a separately encoded excerpt of the same clip.");}
$("#media-dialog").addEventListener("close",()=>{const video=$("#tour-video");if(video){video.pause();video.removeAttribute("src");video.load();}$("#media-content").replaceChildren();});
function setInquiryTab(info){$("#visit-tab").setAttribute("aria-selected",String(!info));$("#info-tab").setAttribute("aria-selected",String(info));$("#visit-tab").tabIndex=info?-1:0;$("#info-tab").tabIndex=info?0:-1;$("#visit-fields").hidden=info;$("#time-note").hidden=info;$$("input,select",$("#visit-fields")).forEach(el=>{el.disabled=info;el.required=!info;});$("#inquiry-form").hidden=false;$("#inquiry-receipt").hidden=true;$("#inquiry-receipt").replaceChildren();}
function openSchedule(info=false){if($("#drawer").open)closeDrawer();$("#inquiry-form").reset();setInquiryTab(info);const date=new Date();date.setDate(date.getDate()+1);const local=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;$("#inquiry-form [name=date]").min=local;$("#schedule-dialog").showModal();}
$("#visit-tab").addEventListener("click",()=>setInquiryTab(false));$("#info-tab").addEventListener("click",()=>setInquiryTab(true));
$$(".inquiry-tabs [role=tab]").forEach(el=>el.addEventListener("keydown",e=>{if(["ArrowLeft","ArrowRight","Home","End"].includes(e.key)){e.preventDefault();const info=e.key==="End"?true:e.key==="Home"?false:$("#info-tab").getAttribute("aria-selected")!=="true";setInquiryTab(info);$(info?"#info-tab":"#visit-tab").focus();}}));
$("#inquiry-form").addEventListener("input",e=>e.target.setCustomValidity?.(""));
$("#inquiry-form").addEventListener("submit",e=>{e.preventDefault();const form=e.currentTarget,name=form.elements.name;if(name.value.trim().length<2){name.setCustomValidity("Enter at least two non-space characters.");name.reportValidity();return;}if(!form.reportValidity())return;const info=$("#info-tab").getAttribute("aria-selected")==="true",receipt=$("#inquiry-receipt"),heading=document.createElement("h3"),copy=document.createElement("p"),contact=document.createElement("p");heading.textContent="Preview ready. Nothing was sent.";copy.textContent=info?`${name.value.trim()}, this is your information-request preview. No agent has received it.`:`${name.value.trim()}, your preferred date is ${form.elements.date.value} at ${form.elements.time.value} Central time. No appointment has been booked.`;contact.textContent=`Email entered for this preview: ${form.elements.email.value.trim()}. Contact details are cleared when this dialog closes.`;receipt.replaceChildren(heading,copy,contact);const message=form.elements.message.value.trim();if(message){const p=document.createElement("p");p.textContent=message;receipt.append(p);}form.reset();form.hidden=true;receipt.hidden=false;});
$("#schedule-dialog").addEventListener("close",()=>{$("#inquiry-form").reset();$("#inquiry-form").hidden=false;$("#inquiry-receipt").replaceChildren();$("#inquiry-receipt").hidden=true;});
function quatMultiply(a,b){return[a[0]*b[3]+a[3]*b[0]+a[1]*b[2]-a[2]*b[1],a[1]*b[3]+a[3]*b[1]+a[2]*b[0]-a[0]*b[2],a[2]*b[3]+a[3]*b[2]+a[0]*b[1]-a[1]*b[0],a[3]*b[3]-a[0]*b[0]-a[1]*b[1]-a[2]*b[2]];}
function orientationPose(e){const x=rad(e.beta),y=rad(e.alpha),z=rad(-e.gamma),c1=Math.cos(x/2),c2=Math.cos(y/2),c3=Math.cos(z/2),s1=Math.sin(x/2),s2=Math.sin(y/2),s3=Math.sin(z/2),angle=rad(screen.orientation?.angle||0);let q=[s1*c2*c3+c1*s2*s3,c1*s2*c3-s1*c2*s3,c1*c2*s3-s1*s2*c3,c1*c2*c3+s1*s2*s3];q=quatMultiply(quatMultiply(q,[-Math.SQRT1_2,0,0,Math.SQRT1_2]),[0,0,-Math.sin(angle/2),Math.cos(angle/2)]);const fx=-2*(q[0]*q[2]+q[3]*q[1]),fy=-2*(q[1]*q[2]-q[3]*q[0]),fz=-(1-2*(q[0]*q[0]+q[1]*q[1]));return{yaw:Math.atan2(fx,-fz)*180/Math.PI,pitch:Math.asin(clamp(fy,-1,1))*180/Math.PI};}
window.addEventListener("deviceorientation",e=>{if(!gyroOn||![e.alpha,e.beta,e.gamma].every(v=>typeof v==="number"&&Number.isFinite(v)))return;const pose=orientationPose(e);if(!gyroBase){gyroBase={...pose,viewYaw:main.yaw,viewPitch:main.pitch};return;}const delta=((pose.yaw-gyroBase.yaw+540)%360)-180;main.set(gyroBase.viewYaw+delta,gyroBase.viewPitch+pose.pitch-gyroBase.pitch);});
screen.orientation?.addEventListener("change",()=>gyroBase=null);
async function setGyro(value){gyroOn=false;gyroBase=null;if(value){let message;try{if(typeof DeviceOrientationEvent==="undefined")throw Error("Motion sensors are unavailable in this browser.");if(typeof DeviceOrientationEvent.requestPermission==="function"&&await DeviceOrientationEvent.requestPermission()!=="granted")throw Error("Motion access was denied.");gyroOn=true;pauseGuide();setRotate(false);message="Motion controls enabled. Waiting for device readings; drag remains available.";}catch(e){message=`${e.message} Drag to explore instead.`;}toast(message);if($("#device-note"))$("#device-note").textContent=message;}if($("#gyro-toggle"))$("#gyro-toggle").checked=gyroOn;}
async function setMusic(value){if(!value){musicNodes.forEach(n=>n.stop?.());musicNodes=[];await musicContext?.close();musicContext=null;musicOn=false;return;}try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error();musicContext=new Audio();await musicContext.resume();const gain=musicContext.createGain();gain.gain.value=.025;gain.connect(musicContext.destination);for(const hz of[130.8128,164.8138,195.9977]){const oscillator=musicContext.createOscillator();oscillator.type="sine";oscillator.frequency.value=hz;oscillator.connect(gain);oscillator.start();musicNodes.push(oscillator);}musicOn=true;}catch{musicOn=false;await musicContext?.close();musicContext=null;toast("Ambient sound is unavailable in this browser.");}if($("#music-toggle"))$("#music-toggle").checked=musicOn;}
if(navigator.xr)navigator.xr.isSessionSupported("immersive-vr").then(value=>xrSupported=value).catch(()=>{});
async function startVR(){
 if(xrSession){await xrSession.end();return;}if(!navigator.xr||!xrSupported){toast("VR is unavailable here. Use a supported WebXR browser, secure URL and compatible headset.");if($("#device-note"))$("#device-note").textContent="No compatible immersive VR session is available in this browser.";return;}
 try{if(compareOpen)openCompare();pauseGuide();setRotate(false);await main.gl.makeXRCompatible();const session=await navigator.xr.requestSession("immersive-vr",{optionalFeatures:["local-floor"]});xrSession=session;session.updateRenderState({baseLayer:new XRWebGLLayer(session,main.gl)});const space=await session.requestReferenceSpace("local");main.xr=true;const base=rotation(main.yaw,main.pitch);
  session.addEventListener("end",()=>{main.xr=false;xrSession=null;main.gl.bindFramebuffer(main.gl.FRAMEBUFFER,null);main.draw();toast("VR session ended.");},{once:true});
  const frame=(time,xrFrame)=>{if(!xrSession)return;session.requestAnimationFrame(frame);const pose=xrFrame.getViewerPose(space);if(!pose)return;const layer=session.renderState.baseLayer;main.gl.bindFramebuffer(main.gl.FRAMEBUFFER,layer.framebuffer);for(const view of pose.views){const m=view.transform.matrix,p=view.projectionMatrix,r=[m[0],m[1],m[2],m[4],m[5],m[6],m[8],m[9],m[10]];main.draw(multiply3(base,r),[p[0],p[5],p[8],p[9]],layer.getViewport(view));}};session.requestAnimationFrame(frame);
 }catch{if(xrSession){await xrSession.end().catch(()=>{});xrSession=null;}main.xr=false;main.draw();toast("VR could not start or permission was declined. The standard tour remains available.");}
}
document.addEventListener("click",e=>{
 const target=e.target.closest("button,a");if(!target){if(!e.target.closest("#hotspot-card"))closeHotspot();return;}
 if(target.matches("[data-room]")){changeRoom(Number(target.dataset.room));if($("#drawer").open)closeDrawer();}
 else if(target.matches("[data-panel]"))openDrawer(target.dataset.panel);
 else if(target.matches("[data-share]"))openDrawer("share");
 else if(target.matches("[data-schedule]"))openSchedule();
 else if(target.matches("[data-more-info]"))openSchedule(true);
 else if(target.matches("[data-close-drawer]"))closeDrawer();
 else if(target.matches("[data-close-schedule]"))$("#schedule-dialog").close();
 else if(target.matches("[data-close-media]"))$("#media-dialog").close();
 else if(target.matches("[data-close-hotspot]"))closeHotspot();
 else if(target.matches("[data-point]"))openPoint(Number(target.dataset.point));
 else if(target.matches("[data-panel-point]")){const index=Number(target.dataset.panelPoint);closeDrawer();openPoint(index);}
 else if(target.matches("[data-photo]"))openPhoto(room(),Number(target.dataset.photo));
 else if(target.matches("[data-gallery-room]"))openPhoto(rooms[Number(target.dataset.galleryRoom)]);
 else if(target.matches("[data-video]"))openVideo(target.dataset.video);
 else if(target.matches("[data-copy]"))copyField(target.dataset.copy);
 else if(target.matches("[data-compare]")){closeDrawer();openCompare();}
 else if(target.id==="clear-measure"){measurePoints=[];drawMeasurement();}
 else if(target.id==="rotate-sofa"){sofaState.rotated=!sofaState.rotated;updateSofa();}
 else if(target.id==="vr-start")startVR();
 else if(target.matches('a[href="#listing-summary"]')&&document.fullscreenElement){e.preventDefault();document.exitFullscreen().then(()=>{location.hash="listing-summary";$("#listing-summary").focus({preventScroll:true});});}
 else if(!target.closest("#hotspot-card"))closeHotspot();
});
document.addEventListener("change",async e=>{
 const el=e.target;
 if(el.id==="mini-toggle")setMini(el.checked);
 if(el.id==="contrast-toggle"){highContrast=el.checked;document.body.classList.toggle("high-contrast",highContrast);}
 if(el.id==="motion-toggle"){reduced=el.checked;document.body.classList.toggle("reduced-motion",reduced);if(reduced)setRotate(false);}
 if(el.id==="gyro-toggle")setGyro(el.checked);
 if(el.id==="music-toggle")setMusic(el.checked);
 if(el.id==="quality-select"){quality=el.value;await main.load(room());if(compareOpen)await reference.load(reference.room);}
 if(el.id==="measure-room"){pauseGuide();current=Number(el.value);updateRoomUI();main.load(room());renderMeasurement($("#drawer-content"));}
});
document.addEventListener("input",e=>{if(["sofa-width","sofa-depth"].includes(e.target.id))updateSofa();if(e.target.id==="lighting-slider")$("#lighting-warm").style.clipPath=`inset(0 ${100-Number(e.target.value)}% 0 0)`;});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeHotspot();});
for(const dialog of $$("dialog"))dialog.addEventListener("click",e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
document.addEventListener("visibilitychange",()=>{if(document.hidden){pauseGuide();setRotate(false);if("speechSynthesis"in window)speechSynthesis.cancel();if(musicOn)setMusic(false);}});
window.addEventListener("pagehide",()=>{pauseGuide();setRotate(false);if(musicOn)setMusic(false);if(xrSession)xrSession.end().catch(()=>{});});
document.body.classList.toggle("reduced-motion",reduced);setMini(miniVisible);const initial=rooms.findIndex(r=>location.hash===`#room=${r.id}`);current=initial>=0?initial:0;updateRoomUI();main.load(room());
